window.SmartRisk=window.SmartRisk||{};(function(){const SR=SmartRisk,esc=v=>SR.Utils.escapeHtml(v??"");
function data(){return SR.ENOSData||{meta:{},gads:[]}}
function statusBadge(v){const cls=v==="Atribuible"?"badge-success":v==="Sin registro"||v==="Sin detalle"?"badge-danger":"badge-warning";return `<span class="badge ${cls}">${esc(v)}</span>`}
function breachBadge(v){return `<span class="badge ${v==="CRÍTICO"?"badge-danger":"badge-warning"}">${esc(v)}</span>`}
function provinceCards(rows){const m={};rows.forEach(x=>{m[x.provincia]??={total:0,critical:0,f07:0};m[x.provincia].total++;if(x.brecha==="CRÍTICO")m[x.provincia].critical++;if(Number(x.f07Registros)>0)m[x.provincia].f07++});return `<section class="territory-summary">${Object.entries(m).sort((a,b)=>b[1].total-a[1].total).map(([p,x])=>`<article class="territory-summary-card"><span>${esc(p)}</span><strong>${x.total}</strong><small class="muted">${x.critical} críticos · ${x.f07} con F07 detectado</small></article>`).join("")}</section>`}
function rowsHtml(rows){return rows.map(x=>`<tr><td>${x.id}</td><td><strong>${esc(x.gad)}</strong><div class="muted" style="white-space:normal;min-width:260px;margin-top:4px">${esc(x.hallazgo)}</div></td><td>${esc(x.provincia)}</td><td>${breachBadge(x.brecha)}</td><td>${statusBadge(x.f01)}</td><td>${statusBadge(x.f04)}</td><td>${statusBadge(x.f07)}<div class="muted" style="margin-top:4px">${x.f07Registros} reg. · ${esc(x.f07Periodo)}</div></td><td>${x.f07Evidencias}</td><td>${x.f07Vinculados}</td></tr>`).join("")||'<tr><td colspan="9">No hay resultados para los filtros seleccionados.</td></tr>'}
function render(){const d=data(),rows=d.gads||[],m=d.meta||{},provs=[...new Set(rows.map(x=>x.provincia))].sort();return `<section class="page-header"><div><span class="kicker">ENOS 2026–2027</span><h1 class="page-title">Matriz territorial · 56 GAD</h1><p class="page-subtitle">Consulta operativa de F01–F07, brechas y hallazgos de la matriz consolidada.</p></div></section><div class="indicator-note"><strong>Actualización de plataforma:</strong> ${esc(m.matrixUpdatedAt||"—")} · <strong>Corte F07:</strong> ${esc(m.f07Cutoff||"—")} · <strong>Auditoría:</strong> ${esc(m.auditDate||"—")}</div>${provinceCards(rows)}<div class="toolbar" style="align-items:stretch;flex-wrap:wrap"><div class="search-wrap"><span class="search-icon">${SR.Icon.render("search",17)}</span><input id="territory-search" class="search-input" placeholder="Buscar GAD o hallazgo"></div><select id="territory-province" class="select-input" style="width:auto"><option value="">Todas las provincias</option>${provs.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join("")}</select><select id="territory-gap" class="select-input" style="width:auto"><option value="">Todas las brechas</option><option>CRÍTICO</option><option>ALTO</option></select><select id="territory-f07" class="select-input" style="width:auto"><option value="">Todo F07</option><option>Atribuible</option><option>Conciliar</option><option>Referencia</option><option>Sin registro</option><option>Sin detalle</option></select><span id="territory-count" class="badge">${rows.length} registros</span></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>N.º</th><th>GAD / hallazgo</th><th>Provincia</th><th>Brecha</th><th>F01</th><th>F04</th><th>F07 / periodo</th><th>Evid.</th><th>Vínc.</th></tr></thead><tbody id="territory-body">${rowsHtml(rows)}</tbody></table></div></div>`}
function bind(){const d=data(),all=d.gads||[],q=document.getElementById("territory-search"),p=document.getElementById("territory-province"),g=document.getElementById("territory-gap"),f=document.getElementById("territory-f07"),body=document.getElementById("territory-body"),count=document.getElementById("territory-count");const apply=()=>{const term=SR.Utils.normalizeText(q?.value||"");const rows=all.filter(x=>(!term||SR.Utils.normalizeText(`${x.gad} ${x.hallazgo}`).includes(term))&&(!p?.value||x.provincia===p.value)&&(!g?.value||x.brecha===g.value)&&(!f?.value||x.f07===f.value));body.innerHTML=rowsHtml(rows);count.textContent=`${rows.length} registros`};[q,p,g,f].forEach(el=>el?.addEventListener(el===q?"input":"change",apply))}
SR.TerritoriosModule={route:{path:"/territorios",title:"Territorios ENOS",render,bind}}})();